from readonly import *
INTENT="Current selected metadata for precisely scoped historical Run/dispatch/effects/cost and receipt counts; no payload, request/response text or BLOB values."
h=scope["historical_subject_reference_only"];p=h["project_id"];r=h["run_id"]
SQL=[
 {"name":"run_current_selected_metadata","sql":"SELECT id,revision,json_extract(body,'$.status') AS status,json_extract(body,'$.lease_epoch') AS lease_epoch,json_extract(body,'$.task_id') AS task_id,json_extract(body,'$.updated_at') AS updated_at FROM domain_objects WHERE project=? AND kind='Run' AND id=? LIMIT 2","params":[p,r],"row_cap":2},
 {"name":"dispatch_current_selected_metadata","sql":"SELECT project,run,epoch,dispatch_key,state,observation_sequence,prepared_at,updated_at FROM runtime_dispatches WHERE project=? AND run=? AND dispatch_key=? ORDER BY epoch LIMIT 16","params":[p,r,h["dispatch_key"]],"row_cap":16},
 {"name":"effect_selected_history","sql":"SELECT effect_key,sequence,json_extract(body,'$.state') AS state,json_extract(body,'$.epoch') AS epoch,json_extract(body,'$.payload.capability') AS capability,json_extract(body,'$.receipt.state') AS receipt_state,json_extract(body,'$.receipt.model_transport') AS model_transport,json_type(body,'$.receipt.actual_cost') AS actual_cost_json_type FROM resource_effects WHERE project=? AND run=? ORDER BY effect_key,sequence LIMIT 64","params":[p,r],"row_cap":64},
 {"name":"latest_effect_metadata_counts","sql":"SELECT json_extract(x.body,'$.state') AS state,json_extract(x.body,'$.payload.capability') AS capability,count(*) AS count FROM resource_effects x WHERE project=? AND run=? AND sequence=(SELECT max(y.sequence) FROM resource_effects y WHERE y.project=x.project AND y.run=x.run AND y.effect_key=x.effect_key) GROUP BY 1,2 ORDER BY 1,2 LIMIT 16","params":[p,r],"row_cap":16},
 {"name":"budget_cost_metadata_counts","sql":"SELECT json_extract(body,'$.operation') AS operation,json_extract(body,'$.cost_basis') AS cost_basis,json_type(body,'$.money') AS money_type,count(*) AS count FROM domain_objects WHERE project=? AND kind='BudgetLedgerEntry' AND json_extract(body,'$.run_id')=? GROUP BY 1,2,3 ORDER BY 1,2,3 LIMIT 32","params":[p,r],"row_cap":32},
 {"name":"historical_request_current_domain_metadata","sql":"SELECT kind,id,revision,json_extract(body,'$.status') AS status,json_extract(body,'$.state') AS state,json_extract(body,'$.consumed') AS consumed FROM domain_objects WHERE project=? AND id=? LIMIT 8","params":[p,h["request_id"]],"row_cap":8},
 {"name":"request_resolution_count","sql":"SELECT count(*) AS count FROM resource_resolutions WHERE project=? AND request=?","params":[p,h["request_id"]],"row_cap":1},
 {"name":"scoped_model_observation_receipts","sql":"SELECT count(*) AS count,min(json_extract(body,'$.observation.sequence')) AS min_sequence,max(json_extract(body,'$.observation.sequence')) AS max_sequence FROM client_control_receipts WHERE project=? AND kind='MODEL_STREAM_OBSERVATION_V1' AND json_extract(body,'$.observation.binding.run_id')=?","params":[p,r],"row_cap":1},
 {"name":"scoped_receipt_kind_counts","sql":"SELECT kind,count(*) AS count FROM client_control_receipts WHERE project=? AND (json_extract(body,'$.run_id')=? OR json_extract(body,'$.observation.binding.run_id')=?) GROUP BY kind ORDER BY kind LIMIT 32","params":[p,r,r],"row_cap":32},
 {"name":"latest_runtime_observation_public_metadata","sql":"SELECT epoch,observed_at,json_extract(body,'$.children_stopped') AS children_stopped,json_extract(body,'$.queue_empty') AS queue_empty,json_extract(body,'$.status') AS status FROM runtime_observations WHERE project=? AND run=? ORDER BY observed_at DESC LIMIT 3","params":[p,r],"row_cap":3}
]
if __name__=="__main__":query_group("g06",SQL)

